import express from 'express';
import fs from 'node:fs';
import tzlookup from 'tz-lookup';

/**
 * Worldwide location service.
 *
 * Place data comes from GeoNames (CC BY 4.0) and is generated by
 * scripts/build-geo-data.mjs into server/data/world-places.json:
 * every ISO 3166-1 country and territory, and every populated place with
 * 5,000+ inhabitants. Nothing here invents a coordinate: a place is only ever
 * returned from the committed dataset or from a live geocoder response.
 *
 * Small villages below the dataset threshold are looked up from the Open-Meteo
 * geocoding API, which returns the coordinates and IANA timezone itself.
 */
export const geoRouter = express.Router();

const DATA_FILE = new URL('./data/world-places.json', import.meta.url);
const raw = JSON.parse(fs.readFileSync(DATA_FILE, 'utf8'));

export const DATASET = {
  generated: raw.generated,
  source: raw.source,
  attribution: 'Place data © GeoNames contributors, licensed CC BY 4.0.',
};

const flagOf = (code) =>
  code && code.length === 2
    ? String.fromCodePoint(...[...code.toUpperCase()].map((c) => 127397 + c.charCodeAt(0)))
    : '';

/** Lowercase, accent-free form so "São Paulo" and "sao paulo" match. */
const norm = (s) =>
  String(s || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .trim();

/* ------------------------------- the dataset ------------------------------- */

const countries = raw.countries.map((c) => ({
  ...c,
  flag: flagOf(c.code),
}));
const countryByCode = new Map(countries.map((c) => [c.code, c]));

/** [name, countryIdx, regionIdx, lat, lon, tzIdx, population, isCapital, aliases] */
const places = raw.cities.map(([name, ci, ri, lat, lon, tzi, population, capital, aliases]) => {
  const countryCode = raw.codes[ci];
  const alias = String(aliases || '')
    .split('|')
    .filter(Boolean);
  return {
    city: name,
    countryCode,
    region: raw.regions[ri] || '',
    lat,
    lon,
    timezone: raw.zones[tzi] || 'UTC',
    population,
    capital: capital === 1,
    key: norm(name),
    // Familiar spellings from GeoNames ("Hargeisa" for Hargeysa, Arabic مقديشو)
    aliasKey: alias.length ? norm(alias.join(' ')) : '',
    countryKey: countryCode,
  };
});

const byCountry = new Map();
for (const p of places) {
  if (!byCountry.has(p.countryCode)) byCountry.set(p.countryCode, []);
  byCountry.get(p.countryCode).push(p);
}

const safeTz = (lat, lon) => {
  try {
    return tzlookup(lat, lon);
  } catch {
    return 'UTC';
  }
};

/** Shape a dataset row for the client, which localises the country name. */
function toPlace(p) {
  const country = countryByCode.get(p.countryCode);
  return {
    city: p.city,
    name: p.city,
    region: p.region,
    country: country?.en || p.countryCode,
    countryAr: country?.ar || '',
    countryCode: p.countryCode,
    flag: country?.flag || flagOf(p.countryCode),
    lat: p.lat,
    lon: p.lon,
    timezone: p.timezone,
    population: p.population,
    capital: p.capital,
    manual: false,
    source: 'GeoNames worldwide place database',
  };
}

/* --------------------------------- ranking -------------------------------- */

const score = (place, q) => {
  if (place.key === q) return 0;
  if (place.key.startsWith(q)) return 1;
  const word = place.key.indexOf(` ${q}`);
  if (word !== -1) return 2;
  if (place.key.includes(q)) return 3;
  // Alternate spellings rank just below the primary name so "Hargeisa" and
  // "Muqdisho" reach the same city as "Hargeysa" and "Mogadishu".
  if (place.aliasKey) {
    if (place.aliasKey.startsWith(q) || place.aliasKey.includes(` ${q}`)) return 2;
    if (place.aliasKey.includes(q)) return 4;
  }
  return -1;
};

/**
 * Search the committed worldwide dataset. Returns the best matches ordered by
 * match quality and then by population, so "Mogadishu" beats a tiny namesake.
 */
export function searchPlaces(query, { country = '', limit = 12 } = {}) {
  const q = norm(query);
  if (q.length < 2) return [];
  const pool = country ? byCountry.get(String(country).toUpperCase()) || [] : places;
  const hits = [];
  for (const p of pool) {
    const s = score(p, q);
    if (s >= 0) hits.push([s, p]);
  }
  hits.sort((a, b) => a[0] - b[0] || b[1].population - a[1].population);
  return hits.slice(0, limit).map(([, p]) => toPlace(p));
}

/** Biggest places of a country — the instant city list after picking a country. */
export function placesInCountry(code, { limit = 400 } = {}) {
  const list = byCountry.get(String(code).toUpperCase()) || [];
  return [...list].sort((a, b) => b.population - a.population).slice(0, limit).map(toPlace);
}

/** Closest known place to a coordinate, used when reverse geocoding is vague. */
export function nearestPlace(lat, lon, { limit = 3 } = {}) {
  let best = [];
  for (const p of places) {
    const dLat = (p.lat - lat) * 111.32;
    const dLon = (p.lon - lon) * 111.32 * Math.cos((lat * Math.PI) / 180);
    const d = dLat * dLat + dLon * dLon;
    if (best.length < limit) {
      best.push([d, p]);
      best.sort((a, b) => a[0] - b[0]);
    } else if (d < best[best.length - 1][0]) {
      best[best.length - 1] = [d, p];
      best.sort((a, b) => a[0] - b[0]);
    }
  }
  return best.map(([d, p]) => ({ ...toPlace(p), distanceKm: Number(Math.sqrt(d).toFixed(2)) }));
}

export function listCountries() {
  return countries;
}

/* ----------------------------- remote fallback ----------------------------- */

const remoteCache = new Map();
const REMOTE_TTL = 24 * 60 * 60 * 1000;
const UA = 'RIFQMuslim/1.0 (Islamic app; contact mohamoudistanbul@gmail.com)';

/**
 * Villages and very small towns are below the dataset threshold, so they are
 * resolved from Open-Meteo's geocoder (no key required, returns the IANA
 * timezone with each hit). A failure degrades to dataset-only results.
 */
async function searchRemote(query, limit) {
  const key = `${norm(query)}|${limit}`;
  const hit = remoteCache.get(key);
  if (hit && Date.now() - hit.at < REMOTE_TTL) return hit.rows;
  const url =
    'https://geocoding-api.open-meteo.com/v1/search?count=' +
    `${Math.min(20, Math.max(5, limit))}&language=en&format=json&name=` +
    encodeURIComponent(query);
  const res = await fetch(url, {
    headers: { 'User-Agent': UA, Accept: 'application/json' },
    signal: AbortSignal.timeout(9000),
  });
  if (!res.ok) throw new Error(`Geocoder responded ${res.status}`);
  const data = await res.json();
  const rows = (data.results || [])
    // Populated places only: airports, admin areas and hotels are not cities.
    .filter((r) => /^PPL/.test(String(r.feature_code || '')))
    .map((r) => ({
      city: r.name,
      name: r.name,
      region: r.admin1 || '',
      country: r.country || '',
      countryAr: countryByCode.get(r.country_code)?.ar || '',
      countryCode: String(r.country_code || '').toUpperCase(),
      flag: flagOf(String(r.country_code || '')),
      lat: Number(r.latitude),
      lon: Number(r.longitude),
      timezone: r.timezone || safeTz(Number(r.latitude), Number(r.longitude)),
      population: Number(r.population) || 0,
      capital: false,
      manual: false,
      source: 'Open-Meteo geocoding',
    }))
    .filter((r) => Number.isFinite(r.lat) && Number.isFinite(r.lon));
  remoteCache.set(key, { at: Date.now(), rows });
  return rows;
}

/* ---------------------------------- routes --------------------------------- */

geoRouter.get('/geo/countries', (_req, res) => {
  res.json({
    countries: countries.map((c) => ({
      code: c.code,
      en: c.en,
      ar: c.ar,
      flag: c.flag,
      capital: c.capital,
      continent: c.continent,
      cities: c.cities,
    })),
    total: countries.length,
    ...DATASET,
  });
});

/** Instant city list for one country (largest first) or a scoped search. */
geoRouter.get('/geo/cities', (req, res) => {
  const code = String(req.query.country || '').toUpperCase();
  if (!/^[A-Z]{2}$/.test(code) || !countryByCode.has(code)) {
    return res.status(400).json({ error: 'A valid ISO country code is required.' });
  }
  const q = String(req.query.q || '').trim();
  const limit = Math.min(500, Math.max(1, Number(req.query.limit) || 200));
  const cities = q.length >= 2 ? searchPlaces(q, { country: code, limit }) : placesInCountry(code, { limit });
  res.json({
    country: countryByCode.get(code),
    cities,
    count: cities.length,
    source: DATASET.source,
  });
});

/** Worldwide search: dataset first, live geocoder for anything smaller. */
geoRouter.get('/geo/search', async (req, res) => {
  const q = String(req.query.q || '').trim();
  const country = /^[A-Za-z]{2}$/.test(String(req.query.country || ''))
    ? String(req.query.country).toUpperCase()
    : '';
  const limit = Math.min(25, Math.max(1, Number(req.query.limit) || 12));
  if (q.length < 2) return res.json({ results: [], count: 0, source: 'none' });

  const local = searchPlaces(q, { country, limit });
  let rows = local;
  let degraded = false;
  let note = '';

  if (local.length < limit) {
    try {
      const remote = await searchRemote(q, limit);
      const seen = new Set(local.map((r) => `${norm(r.city)}|${r.countryCode}|${r.lat.toFixed(2)}`));
      const extra = remote.filter((r) => {
        if (country && r.countryCode !== country) return false;
        const k = `${norm(r.city)}|${r.countryCode}|${r.lat.toFixed(2)}`;
        if (seen.has(k)) return false;
        seen.add(k);
        return true;
      });
      rows = [...local, ...extra].slice(0, limit);
    } catch (err) {
      degraded = true;
      note = `Live geocoder unavailable (${err.message}); showing the offline place database.`;
    }
  }

  res.json({
    results: rows,
    count: rows.length,
    country: country || null,
    degraded,
    ...(note ? { note } : {}),
    source: degraded
      ? DATASET.source
      : 'GeoNames worldwide place database + Open-Meteo geocoding for small localities',
  });
});

/**
 * Reverse geocode real coordinates. The city name comes from a live reverse
 * geocoder; the coordinate itself and the IANA timezone are always computed
 * locally, so a geocoder outage can never produce a guessed location.
 */
geoRouter.get('/geo/reverse', async (req, res) => {
  const lat = Number(req.query.lat);
  const lon = Number(req.query.lon);
  if (!Number.isFinite(lat) || !Number.isFinite(lon) || Math.abs(lat) > 90 || Math.abs(lon) > 180) {
    return res.status(400).json({ error: 'Valid latitude and longitude are required.' });
  }
  const timezone = safeTz(lat, lon);
  const near = nearestPlace(lat, lon, { limit: 1 })[0] || null;
  try {
    const r = await fetch(
      'https://api.bigdatacloud.net/data/reverse-geocode-client' +
        `?latitude=${lat}&longitude=${lon}&localityLanguage=en`,
      { headers: { 'User-Agent': UA, Accept: 'application/json' }, signal: AbortSignal.timeout(9000) }
    );
    if (!r.ok) throw new Error(`Reverse geocoder responded ${r.status}`);
    const data = await r.json();
    const countryCode = String(data.countryCode || near?.countryCode || '').toUpperCase();
    const country = countryByCode.get(countryCode);
    const city = data.city || data.locality || near?.city || data.principalSubdivision || '';
    res.json({
      city: city || 'Location unavailable',
      locality: data.locality || '',
      region: data.principalSubdivision || near?.region || '',
      regionCode: data.principalSubdivisionCode || '',
      country: data.countryName || country?.en || '',
      countryCode,
      flag: flagOf(countryCode),
      lat,
      lon,
      timezone,
      nearest: near,
      source: 'BigDataCloud reverse geocoding + GeoNames nearest place + tz-lookup',
      manual: false,
    });
  } catch (err) {
    res.json({
      city: near?.city || 'Location unavailable',
      locality: '',
      region: near?.region || '',
      country: countryByCode.get(near?.countryCode)?.en || '',
      countryCode: near?.countryCode || '',
      flag: flagOf(near?.countryCode || ''),
      lat,
      lon,
      timezone,
      nearest: near,
      degraded: true,
      source: 'GeoNames nearest place + tz-lookup (reverse geocoder unreachable)',
      note: `City name lookup failed: ${err.message}`,
      manual: false,
    });
  }
});
